import Link from "next/link";
import { getProducts } from "@/services/productService";
import ProductCard from "@/components/ProductCard";

export default async function Home() {
  const products = await getProducts();

  return (
    <div className="container mx-auto px-6 py-10">

      {/* HERO SECTION */}
      <section className="bg-white rounded-2xl shadow-sm p-10 mb-12 flex items-center justify-between">
        <div>
          <h1 className="text-4xl font-bold mb-4">
            Welcome to Women Hub ✨
          </h1>

          <p className="text-gray-600 mb-6 max-w-lg">
            Discover stylish, comfortable and premium products made
            specially for women. Fashion, fitness and lifestyle —
            everything in one place.
          </p>

          <Link
            href="/products"
            className="bg-black text-white px-6 py-3 rounded-lg hover:bg-gray-800 transition"
          >
            Shop Now
          </Link>
        </div>

        <img
          src="https://via.placeholder.com/400x250?text=Women+Hub"
          alt="Hero"
          className="rounded-xl hidden md:block"
        />
      </section>

      {/* FEATURED PRODUCTS */}
      <section>
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-2xl font-semibold">
            Latest Products
          </h2>

          <Link
            href="/products"
            className="text-sm font-medium text-gray-600 hover:text-black"
          >
            View All →
          </Link>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
          {products?.slice(0, 8).map((product) => (
            <ProductCard
              key={product._id}
              product={product}
            />
          ))}
        </div>
      </section>

    </div>
  );
}
